def tabella(catalogo):
    ordinate = sorted(catalogo.items(), key=lambda kv: kv[1]["Ix"], reverse=True)
    return [f"{nome:<10}{s['A']:>10.0f}{s['Ix']:>14.0f}" for nome, s in ordinate]


